// core-sync: 1.0.0 — deterministic routing BEFORE any model call.
// Order: suppressed states -> sensitive -> media-only -> status request -> human request -> model.
const inp = $('When Executed by Another Workflow').first().json;
const resolution = JSON.parse(inp.resolution || '{}');
const sensitiveTypes = JSON.parse(inp.sensitive_types || '[]');
let history = [];
try { const h = $('Sendblue: Recent Conversation History').first().json; history = (h.messages || h.data || (Array.isArray(h) ? h : [])).map(m => ({ dir: m.is_outbound ? 'out' : 'in', content: (m.content || '').slice(0, 400), at: m.date_sent || m.date_created || null })).reverse(); } catch (e) { history = []; }
const text = (inp.inbound_content || '').toLowerCase();
const outcome = resolution.outcome || 'no_match';
let route = 'model';
// RESET is a control word, not a conversation turn. Left to reach the model it scores low
// confidence, which deterministically triggers a human handoff and mutes the assistant for
// this contact — the reset tool silently becomes a kill switch. Suppress it before routing.
const _resetNumbers = String($env.RESET_CONTROL_NUMBERS || '').split(',').map(s => s.trim()).filter(Boolean);
const _isResetWord = text.trim().replace(/[!.?\s]+$/g, '') === 'reset';
const _resetAllowed = String($env.RESET_CONTROL_ENABLED || 'false') === 'true' && _resetNumbers.includes(inp.customer_number);
let suppressReason = null;
if (_isResetWord && _resetAllowed) { route = 'suppress'; suppressReason = 'reset_control_word'; }
else if (['opted_out', 'wrong_number', 'human_takeover', 'ai_disabled'].includes(outcome)) route = 'suppress';
else if (outcome === 'resolver_error') route = 'handoff';
else if (outcome === 'multiple_match') route = 'ambiguous';
else if (sensitiveTypes.length > 0) route = 'sensitive';
else if (inp.has_media && !text.trim()) route = 'media_only';
else if (/(what('|’)?s going on with my (application|file)|where am i in the process|did you (get|receive) my (application|documents|docs)|status of my (application|file|loan)|am i approved|when am i getting funded|who is handling my file|what else do you need)/.test(text)) route = 'status_lookup';
else if (/(talk|speak) to (a |an )?(human|person|agent|rep)|call me|can someone call|real person/.test(text)) route = 'human_request';
const debounced_content = history.filter(h => h.dir === 'in').slice(-3).map(h => h.content).join('\n');
console.log(JSON.stringify({ level: 'info', workflow: 'SB-04', workflow_version: '1.0.0', correlation_id: inp.correlation_id, action: 'route_intent', route, resolution_outcome: outcome, message_handle: inp.message_handle, ts: new Date().toISOString() }));
return [{ json: { ...inp, resolution, sensitive_types_arr: sensitiveTypes, history, route, suppress_reason: suppressReason, debounced_content } }];

// Deterministic template replies (prompts/fallback-messages.json wording, provided via env FALLBACK_MESSAGES_JSON so compliance-approved copy lives in n8n config).
const templates = JSON.parse($env.FALLBACK_MESSAGES_JSON || '{}').templates || {};
const pick = { sensitive: 'sensitive_info_warning', media_only: 'media_redirect_secure_portal', ambiguous: 'ambiguous_record' }[$json.route];
const content = templates[pick] || 'Thanks for your message — a member of our team will follow up shortly.';
return [{ json: { correlation_id: $json.correlation_id, customer_number: $json.customer_number, customer_ref: $json.customer_ref, content, template_id: pick, is_reply_to_inbound: true, record_ref: $json.resolution.sanitized ? $json.resolution.sanitized.record_ref : null, escalate: $json.route === 'ambiguous' || $json.sensitive_types_arr.length > 1 } }];

// core-sync: 1.0.0 — data minimization: ONLY approved context reaches the model.
// Excluded by construction: credentials, tokens, internal notes, other customers' data, owner ids, unapproved underwriting info.
const j = $json;
const sys = ($env.EMMA_SYSTEM_PROMPT || 'You are {{ASSISTANT_NAME}}, a virtual assistant for {{COMPANY_NAME}}. Reply ONLY with the JSON object matching the schema.').replaceAll('{{ASSISTANT_NAME}}', $env.ASSISTANT_NAME || 'Emma').replaceAll('{{COMPANY_NAME}}', $env.COMPANY_NAME || 'Big Think Capital');
const qualRules = JSON.parse($env.QUALIFICATION_RULES_JSON || '{}');
const enabledFields = (qualRules.collectable_fields || []).filter(f => f.enabled).sort((a, b) => a.priority - b.priority);
const s = j.resolution.sanitized || {};
const placeholderCo = $env.SF_COMPANY_PLACEHOLDER || 'Unknown (Sendblue AI intake)';
const kf = s.known_fields || {};
const known = Object.assign({}, kf, { first_name: kf.first_name ?? s.first_name ?? null, business_name: ((kf.business_name ?? s.business_name) === placeholderCo ? null : (kf.business_name ?? s.business_name)) || null });
const missing = enabledFields.filter(f => known[f.key] === null || known[f.key] === undefined || known[f.key] === '').map(f => f.key);
const faq = JSON.parse($env.APPROVED_FAQ_JSON || '{"entries":[]}').entries.filter(e => e.active && e.placeholder_requires_compliance_approval === false && e.required_verification_level === 0).map(e => ({ q: e.approved_question, a: e.approved_answer }));
const context = {
  resolution_outcome: j.resolution.outcome,
  verification_level: 0,
  customer_safe_stage: (s.conversation_stage === 'HUMAN_HANDOFF' && s.human_takeover !== true ? 'QUALIFYING' : s.conversation_stage) || (j.resolution.outcome === 'no_match' ? 'NEW_LEAD' : null),
  salesforce: j.resolution.outcome === 'single_match' ? { first_name: s.first_name, business_name: s.business_name, stage: (s.conversation_stage === 'HUMAN_HANDOFF' && s.human_takeover !== true ? 'QUALIFYING' : s.conversation_stage), application_link_on_file: s.application_link_on_file } : null,
  missing_fields: missing.slice(0, 8),
  known_fields: Object.fromEntries(Object.entries(known).filter(([,v]) => v !== null && v !== undefined && v !== '')),
  approved_faq: faq,
  human_takeover: s.human_takeover === true,
  ai_enabled: s.ai_enabled !== false,
  has_media: j.has_media === true
};
const schema = JSON.parse($env.STRUCTURED_OUTPUT_SCHEMA_JSON || '{}');
// History hygiene: our own fallback templates are not conversational commitments, and a
// customer-texted RESET marker truncates everything before it (tester convenience, harmless in prod).
const fbTemplates = Object.values((JSON.parse($env.FALLBACK_MESSAGES_JSON || '{}').templates) || {});
const fbPrefix = (t) => { const cut = String(t).indexOf('{'); const s = cut > 20 ? String(t).slice(0, cut) : String(t); return s.slice(0, 40); };
const fbPrefixes = fbTemplates.map(fbPrefix).filter(s => s.length >= 20);
const isFallbackText = (txt) => { const s = String(txt || '').trim(); return fbPrefixes.some(pre => s.startsWith(pre)); };
let hist = Array.isArray(j.history) ? j.history.slice() : [];
let resetIdx = -1;
hist.forEach((h, i) => { if (h.dir === 'in' && String(h.content || '').trim().toLowerCase().replace(/[!.?\s]+$/g, '') === 'reset') resetIdx = i; });
if (resetIdx >= 0) hist = hist.slice(resetIdx + 1);
hist = hist.filter(h => !(h.dir !== 'in' && isFallbackText(h.content))).slice(-12);
const userMsg = `CONTEXT:\n${JSON.stringify(context, null, 1)}\n\nRECENT MESSAGES (oldest first):\n${hist.map(h => `${h.dir === 'in' ? 'CUSTOMER' : 'ASSISTANT'}: ${h.content}`).join('\n') || '(none)'}\n\nCURRENT INBOUND MESSAGE:\n${j.inbound_content}\n\nOUTPUT JSON SCHEMA (return exactly one conforming JSON object, nothing else):\n${JSON.stringify(schema)}`;
return [{ json: { ...j, anthropic_request: { model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5', max_tokens: Number($env.ANTHROPIC_MAX_TOKENS || 1024), system: sys, messages: [{ role: 'user', content: userMsg }] } } }];

// core-sync: 1.0.0 — mirrors extractJson/validateStructuredOutput in scripts/lib/agent-core.mjs.
const src = $('Build Sanitized Claude Request').first().json;
const schema = JSON.parse($env.STRUCTURED_OUTPUT_SCHEMA_JSON || '{}');
function extractJson(raw) { const t = String(raw || '').trim(); try { return JSON.parse(t); } catch {} const s = t.indexOf('{'), e = t.lastIndexOf('}'); if (s >= 0 && e > s) { try { return JSON.parse(t.slice(s, e + 1)); } catch {} } return null; }
function validate(obj, sch) { const errors = []; const check = (value, s, p) => { const types = Array.isArray(s.type) ? s.type : [s.type]; const jt = value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value; if (s.type && !types.includes(jt)) { errors.push(p + ': type'); return; } if (s.enum && !s.enum.includes(value)) errors.push(p + ': enum'); if (jt === 'string' && s.maxLength && value.length > s.maxLength) errors.push(p + ': maxLength'); if (jt === 'number') { if (s.minimum !== undefined && value < s.minimum) errors.push(p + ': min'); if (s.maximum !== undefined && value > s.maximum) errors.push(p + ': max'); } if (jt === 'array' && s.items) value.forEach((it, i) => check(it, s.items, p + '[' + i + ']')); if (jt === 'object' && s.properties) { for (const r of s.required || []) if (!(r in value)) errors.push(p + '.' + r + ': missing'); if (s.additionalProperties === false) for (const k of Object.keys(value)) if (!s.properties[k]) errors.push(p + '.' + k + ': extra'); for (const [k, v] of Object.entries(value)) if (s.properties[k]) check(v, s.properties[k], p + '.' + k); } }; if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) return { valid: false, errors: ['root'] }; check(obj, sch, '$'); return { valid: errors.length === 0, errors }; }
let raw = null, apiFailed = false;
try { const resp = $('Claude: Generate Structured Reply').first().json; raw = (Array.isArray(resp.content) ? resp.content.filter(b => b && b.type === 'text').map(b => b.text).join('\n') : '').trim() || null; if (!raw) apiFailed = true; } catch (e) { apiFailed = true; }
const parsed = raw ? extractJson(raw) : null;
const v = parsed ? validate(parsed, schema) : { valid: false, errors: ['no_output'] };
return [{ json: { ...src, model_output: parsed, model_valid: v.valid, model_errors: v.errors, api_failed: apiFailed, attempt: 1 } }];

// core-sync: 1.0.0 — after one failed repair: never send malformed output; safe fallback + log + escalate flag.
const src = $('Validate Structured Output').first().json;
const schema = JSON.parse($env.STRUCTURED_OUTPUT_SCHEMA_JSON || '{}');
function extractJson(raw) { const t = String(raw || '').trim(); try { return JSON.parse(t); } catch {} const s = t.indexOf('{'), e = t.lastIndexOf('}'); if (s >= 0 && e > s) { try { return JSON.parse(t.slice(s, e + 1)); } catch {} } return null; }
function validate(obj, sch) { const errors = []; const check = (value, s, p) => { const types = Array.isArray(s.type) ? s.type : [s.type]; const jt = value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value; if (s.type && !types.includes(jt)) { errors.push(p + ': type'); return; } if (s.enum && !s.enum.includes(value)) errors.push(p + ': enum'); if (jt === 'string' && s.maxLength && value.length > s.maxLength) errors.push(p + ': maxLength'); if (jt === 'number') { if (s.minimum !== undefined && value < s.minimum) errors.push(p + ': min'); if (s.maximum !== undefined && value > s.maximum) errors.push(p + ': max'); } if (jt === 'array' && s.items) value.forEach((it, i) => check(it, s.items, p + '[' + i + ']')); if (jt === 'object' && s.properties) { for (const r of s.required || []) if (!(r in value)) errors.push(p + '.' + r + ': missing'); if (s.additionalProperties === false) for (const k of Object.keys(value)) if (!s.properties[k]) errors.push(p + '.' + k + ': extra'); for (const [k, v] of Object.entries(value)) if (s.properties[k]) check(v, s.properties[k], p + '.' + k); } }; if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) return { valid: false, errors: ['root'] }; check(obj, sch, '$'); return { valid: errors.length === 0, errors }; }
let parsed = null;
try { const resp = $('Claude: One Repair Attempt').first().json; parsed = extractJson((Array.isArray(resp.content) ? resp.content.filter(b => b && b.type === 'text').map(b => b.text).join('\n') : '')); } catch (e) { parsed = null; }
const v = parsed ? validate(parsed, schema) : { valid: false, errors: ['repair_failed'] };
if (v.valid) return [{ json: { ...src, model_output: parsed, model_valid: true, attempt: 2 } }];
console.log(JSON.stringify({ level: 'error', workflow: 'SB-04', correlation_id: src.correlation_id, action: 'model_output_invalid_after_repair', errors: v.errors.slice(0, 5), ts: new Date().toISOString() }));
return [{ json: { ...src, model_output: null, model_valid: false, attempt: 2, use_fallback: true } }];

// core-sync: 1.0.0 — mirrors isActionPermitted/validateOutboundContent in scripts/lib/agent-core.mjs.
// The model RECOMMENDS; this node DECIDES. Claude never changes stages or sends.
const j = $json;
const templates = JSON.parse($env.FALLBACK_MESSAGES_JSON || '{}').templates || {};
const compliance = JSON.parse($env.COMPLIANCE_RULES_JSON || '{}');
const map = JSON.parse($env.SF_FIELD_MAP_JSON || '{}');
const m = map.mappings || {};
const outcome = j.resolution.outcome || 'no_match';
const ALLOWED = { no_match: ['reply_only','create_lead','human_handoff','suppress','no_action','schedule_followup'], single_match: ['reply_only','update_record','lookup_status','send_application_link','schedule_call','schedule_followup','human_handoff','suppress','no_action'], multiple_match: ['human_handoff','suppress','no_action','reply_only'], opted_out: ['suppress','no_action'], wrong_number: ['suppress','no_action'], human_takeover: ['suppress','no_action'], ai_disabled: ['suppress','no_action'] };
function contentOk(content, templateId) { const v = compliance.outbound_validation || {}; const t = String(content || ''); if (v.block_empty && !t.trim()) return { ok: false, reason: 'empty' }; if (v.max_message_length && t.length > v.max_message_length) return { ok: false, reason: 'too_long' }; if (templateId && (v.whitelisted_template_ids || []).includes(templateId)) return { ok: true }; for (const p of v.forbidden_content_patterns || []) { try { if (new RegExp(p, 'i').test(t)) return { ok: false, reason: 'forbidden_pattern' }; } catch {} } return { ok: true }; }
let reply = null, templateId = null, action = 'no_action', handoff = false, handoffReason = null, extracted = {};
if (j.use_fallback || !j.model_valid || !j.model_output) {
  reply = templates.fallback_generic || null; templateId = 'fallback_generic'; action = 'reply_only'; handoff = true; handoffReason = 'invalid_model_output';
} else {
  const o = j.model_output;
  extracted = o.extracted_fields || {};
  action = (ALLOWED[outcome] || ['suppress']).includes(o.requested_action) ? o.requested_action : 'no_action';
  // Injection / sensitive double-checks on OUTPUT
  const markers = (compliance.prompt_injection && compliance.prompt_injection.output_markers) || [];
  const injected = o.detected_intent === 'prompt_injection' || markers.some(mk => (o.reply_text || '').toLowerCase().includes(mk));
  if (injected) { reply = templates.fallback_generic; templateId = 'fallback_generic'; action = 'reply_only'; }
  else if (action === 'suppress' || outcome === 'human_takeover' || outcome === 'ai_disabled') { reply = null; action = 'suppress'; }
  else { reply = o.reply_text || null; }
  const deterministicHandoff = o.confidence < 0.55 || ['complaint','human_request'].includes(o.detected_intent) || outcome === 'multiple_match';
  handoff = deterministicHandoff || (o.request_human_handoff === true && !['greeting','qualification_answer'].includes(o.detected_intent));
  if (o.request_human_handoff === true && !handoff) console.log(JSON.stringify({ level: 'warn', workflow: 'SB-04', correlation_id: j.correlation_id, action: 'handoff_downgraded', intent: o.detected_intent, model_reason: String(o.handoff_reason || '').slice(0, 140), ts: new Date().toISOString() }));
  handoffReason = handoff ? (o.handoff_reason || (o.confidence < 0.55 ? 'low_confidence' : o.detected_intent)) : null;
  if (action === 'reply_only' && outcome === 'single_match' && /\b(application link|secure application|your application\b)/i.test(reply || '')) {
  console.log(JSON.stringify({ level: 'warn', workflow: 'SB-04', correlation_id: j.correlation_id, action: 'upgraded_reply_to_app_link', reason: 'model_referenced_link_without_action', ts: new Date().toISOString() }));
  action = 'send_application_link';
}
if (action === 'send_application_link') { const base = $env.APPLICATION_LINK_BASE_URL; if (base) {
    // Tokenized prefill link: random bearer token resolves to this lead via the SB-12 prefill API.
    let esignLink = base.replace(/\/+$/, '');
    if (j.resolution.record_id) {
      let tok = ''; for (let i = 0; i < 48; i++) tok += Math.floor(Math.random() * 16).toString(16);
      esignLink = esignLink + '/apply?t=' + tok;
      j.esign_token = tok;
    }
    reply = (templates.application_link || 'Here is your secure application link: {application_link}').replace('{application_link}', esignLink); templateId = 'application_link';
  } else { action = 'human_handoff'; handoff = true; handoffReason = 'application_link_not_configured'; } }
}
if (reply) { const c = contentOk(reply, templateId); if (!c.ok) { console.log(JSON.stringify({ level: 'warn', workflow: 'SB-04', correlation_id: j.correlation_id, action: 'blocked_noncompliant_content', reason: c.reason, ts: new Date().toISOString() })); reply = templates.fallback_generic || null; templateId = 'fallback_generic'; handoff = true; handoffReason = handoffReason || 'compliance_block'; } }
// Salesforce write plan — fill-empty-only conflict rule; stage fields NEVER set from model values except the mapped conversation_stage bookkeeping field.
const updates = {};
if (outcome === 'single_match' && ['update_record','send_application_link','schedule_call','reply_only'].includes(action)) {
  const s = j.resolution.sanitized || {};
  const setIf = (logical, current, value) => { const spec = m[logical]; if (!spec || spec.field === 'UNMAPPED' || spec.object !== j.resolution.record_object) return; if (value === null || value === undefined || value === '') return; const rule = (map.conflict_rules && (map.conflict_rules.overrides || {})[logical]) || (map.conflict_rules || {}).default || 'fill_empty_only'; if (rule === 'fill_empty_only' && current) return; updates[spec.field] = value; };
  setIf('first_name', s.first_name, extracted.first_name);
  setIf('business_name', s.business_name && s.business_name !== ($env.SF_COMPANY_PLACEHOLDER || 'Unknown (Sendblue AI intake)') ? s.business_name : null, extracted.business_name);
  setIf('industry', null, extracted.industry);
  setIf('business_state', null, extracted.business_state);
  setIf('time_in_business', null, extracted.time_in_business_months);
  setIf('monthly_gross_revenue', null, extracted.monthly_gross_revenue);
  setIf('requested_amount', null, extracted.requested_amount);
  setIf('use_of_funds', null, extracted.use_of_funds);
  setIf('funding_urgency', null, extracted.funding_urgency);
  setIf('preferred_call_time', null, extracted.preferred_call_time);
  setIf('email', null, extracted.email);
  const liSpec = m.last_inbound_date; if (liSpec && liSpec.field !== 'UNMAPPED' && liSpec.object === j.resolution.record_object) updates[liSpec.field] = new Date().toISOString();  if (action === 'send_application_link' && j.esign_token) {
    const setDirect = (logical, value) => { const spec = m[logical]; if (spec && spec.field !== 'UNMAPPED' && spec.object === j.resolution.record_object) updates[spec.field] = value; };
    setDirect('esign_token', j.esign_token);
    setDirect('esign_token_expiry', new Date(Date.now() + 30 * 86400000).toISOString());
    setDirect('application_link_sent_date', new Date().toISOString());
  }
}
const createLead = outcome === 'no_match' && action === 'create_lead' && ['new_funding_interest','qualification_answer','greeting','application_request'].includes((j.model_output || {}).detected_intent || '');
return [{ json: { correlation_id: j.correlation_id, customer_number: j.customer_number, customer_ref: j.customer_ref, record_ref: j.resolution.sanitized ? j.resolution.sanitized.record_ref : null, record_id: j.resolution.record_id || null, record_object: j.resolution.record_object || null, reply, template_id: templateId, action, handoff, handoff_reason: handoffReason, sf_updates: updates, create_lead: createLead, extracted, history: j.history, is_reply_to_inbound: true } }];

// Emits one item per required side-effect so each branch runs at most once.
const j = $json;
const out = [];
if (j.create_lead) out.push({ json: { ...j, side_effect: 'create_lead' } });
if (Object.keys(j.sf_updates || {}).length && j.record_id) out.push({ json: { ...j, side_effect: 'update' } });
if (j.handoff) out.push({ json: { ...j, side_effect: 'handoff' } });
if (j.reply && j.action !== 'suppress') out.push({ json: { ...j, side_effect: 'send' } });
if (!out.length) out.push({ json: { ...j, side_effect: 'none' } });
return out;
